# The design proposals: one source for the Review board, the proposals page and 03-proposals.md.
# effort S/M/L, risk low/med/high, impact low/med/high. Nothing here is built.

P = [
 dict(id='P-01', title='A header with zones: the "on air" cluster, and a menu for the rest', effort='M', risk='low', impact='high',
  one='13 header controls in one row become three groups: find (search, history), ON AIR (Screens, Hide screen, Message, Open/Close projection) and a ⚙ menu (appearance, Help, Shortcuts, Remote).',
  problem='The header holds 13 controls of four different kinds in one flat row: navigation, search, appearance (theme, contrast), help, and the live controls. Help, Shortcuts, theme and contrast are used once a month; Hide screen, Message and Close projection are used every service, yet look the same. With the screens live at 1040 px the row did not fit (the search button was squeezed to 22 px and the logo overlapped; fixed as a bug, but the cause is the number of controls). At a 150 % interface scale the row needed a second line.',
  change='Left: logo, history, search. Right: one bordered ON AIR cluster (a red outline while the screens are live) with Screens ▾, Hide screen, Message and Open/Close projection. Far right: Remote (shows a phone count when connected) and a ⚙ menu that holds Appearance (theme, high contrast, interface size), Help and Keyboard shortcuts. Seven controls instead of thirteen, and the live ones are grouped where the eye lands first.',
  benefit='Faster to find the screens controls; no wrapping at 1040 px even with the screens live; fewer wrong clicks on a rarely used control; room to add things later without another overflow.',
  files='src/renderer/src/App.tsx (header), App.css (.app-header, .header-actions), components/ScreensMenu.tsx, RemotePanel.tsx; a new small SettingsMenu component reusing ContextMenu.',
  migration='No data change. Shortcuts stay (?, F1, Alt+←/→, ⌘K). The ⚙ menu also lists the shortcut next to each item so v1 users find them.',
  v1='Hide screen / Message / Screens stay in the same screen position (to the right of the search), so muscle memory holds.',
  accept='At 1040×640 with the screens live the header has no overlap and no wrap; every item reachable by keyboard; theme/contrast/size work from the ⚙ menu; the Esc rule is unchanged.'),
 dict(id='P-02', title='One vocabulary for sending something to the screens', effort='S', risk='low', impact='high',
  one='"Project", "Take", "Put on the screen", "Show", "Hide screen", "Blank" and "Clear" are used for overlapping things. Pick one word per job and use it on every surface.',
  problem='The same action is called Project (verse buttons, search results), Take next (live box), "Put verse 1 on the screen" (accessible name), "Tap a verse to put it on screen" (hint), Show (Tape: "Put on the screens"), and the phone says Next/Blank. Hiding is Hide screen / Show screen / Blank / Clear / "Screen hidden" / Esc, depending on where you are. A volunteer who has used the app twice cannot tell whether "Clear" removes the queue item or the live text.',
  change='A short glossary used everywhere (operator app, phone, Help, manual, tooltips): SHOW = send to the screens now; NEXT / BACK = step through the queue; HIDE SCREEN / SHOW SCREEN = the blackout (Esc); CLEAR = remove the text but keep the screens on; PROJECTION = the window (Open / Close). "Project" and "Take" disappear from the UI.',
  benefit='One word to learn per job; the manual and the phone match the app; fewer mistakes about what a button does.',
  files='String changes only: App.tsx, QueuePanel/Preview components, BiblePanel, SongsPanel, SermonFollowView, MediaPanel, Tape components, webRemote.ts (phone), docs/manual. A tests/strings check keeps the glossary.',
  migration='Strings only. Keep the old words as search keywords in the command palette (typing "project" still finds "Show").',
  v1='v1 users know "Project": the palette and Help list "Project = Show". The v1 manual already says Project.',
  accept='A repo test fails if "Project" or "Take" appears in operator-facing strings; the phone and app agree on every label.'),
 dict(id='P-03', title='Service queue: one File menu, one readiness chip, room for more rows', effort='S', risk='low', impact='high',
  one='Seven text buttons in two rows (New, Open, Import, Save, Save + pictures, Open pack, Check) collapse into File ▾ plus an "Is tonight ready?" status chip.',
  problem='The queue toolbar takes two rows (about 70 px) before the first queue row; at 1366×768 the list shows six rows and at 1040×640 only two. "Open" exists four times (rail, toolbar, empty-state button, palette). The phone remote already uses a compact File ▾ / Save / Edit group, so the two surfaces disagree. The readiness check ("Check") is the thing a volunteer needs before service, but it is the quietest word in the row.',
  change='Toolbar: File ▾ (New, Open…, Import…, Save, Save + pictures, Open pack…), Edit, and a status chip: ✓ Ready / ⚠ 2 to fix (opens "Is tonight ready?"). The empty state keeps one "Open a saved service…" button. The rail Open button goes (see P-04).',
  benefit='About 36 px more list height (two more queue rows); the readiness state is visible without opening anything; phone and desktop share the same File pattern.',
  files='components/QueuePanel (toolbar), App.tsx (rail Open), Preflight.tsx (chip data), CommandPalette (same commands), phone: unchanged.',
  migration='No data change. Keyboard: ⌘O / ⌘S unchanged.',
  v1='File ▾ matches the v1 phone remote; v1 desktop had the same text buttons, so the first-time tooltip says "New, Open, Save are under File".',
  accept='Queue list shows ≥ 8 rows at 1366×768; the chip turns amber when a check item fails; every old action reachable in ≤ 2 clicks.'),
 dict(id='P-04', title='Left rail: Find / Tape / Service groups and one selection colour', effort='S', risk='low', impact='med',
  one='Eight rail buttons in one list, each section highlighted in its own colour (green, orange, teal, white, plum). Group them and use one meaning for colour.',
  problem='Selected Bible is green, Songs orange, Media teal, Tape white, Queue plum, Saved and Open plain. Colour is supposed to carry meaning (red = live only, plum = the action colour, blue = screens), so five accent colours that mean nothing but "this section" dilute it. Saved and Open are service-file actions, not places to browse, but sit among the places. On a short window the last buttons fell off the bottom (fixed as a bug: the rail now scrolls).',
  change='Three labelled groups: FIND (Sermons, Bible, Songs, Media), LISTEN (Tape), SERVICE (Queue with its count, Saved, Open moves into File ▾ per P-03). Selected state is one plum wash for all; the section keeps its own colour only inside its own panel (a small stripe), where it helps recognition.',
  benefit='The rail reads at a glance; colour regains its meaning; fewer controls to scan.',
  files='App.tsx (rail), App.css (.rail-btn colour modifiers), TapeRailButton.tsx; themeContrast test already covers the tokens.',
  migration='None. Rail order of the first four stays.', v1='Same icons and order for Sermons, Bible, Songs.',
  accept='One selected colour in all three themes (contrast tests pass); Queue count badge unchanged; keyboard order top to bottom.'),
 dict(id='P-05', title='A "Now" dock: what is on air, the tape, and the connections in one bottom strip', effort='M', risk='med', impact='high',
  one='The status bar (On air · 3 displays · 12 in queue) and the tape bar are two stacked strips; the question "what is on screen right now?" is answered by a small word. Merge them into one 56 px dock.',
  problem='"What is live right now" must be obvious in under a second. Today it is a red "On air" word in a 12 px status bar plus a small LIVE box in the queue pane that disappears when the queue pane is hidden; the tape bar (57 px) sits above the status bar (~30 px), so two strips cost ~87 px of a 640 px window. Connections (screens, stage, phone, OBS) are only visible by opening Screens ▾ or Remote.',
  change='One dock: left zone LIVE (red outline, type icon, title, "on screen 0:42", Hide screen when live; grey "Nothing on screen" when not); middle zone the tape (play, ±10 s, paragraph, seek, volume; hidden with no tape); right zone small status dots for Screens, Stage, Phone, Output with a click-through to a status popover (see backlog: status centre).',
  benefit='"What is live" is answered in one glance in every section, with the queue pane open or shut; about 30 px back; one place for problems.',
  files='components/GlobalTapeBar.tsx/.css, status bar in App.tsx (.status-bar), new NowDock component using useTapeNow and live state; remote unchanged.',
  migration='The tape bar keeps all its behaviour and shortcuts; the status bar text moves. Toast lift (body:has(.gtb)) is updated.',
  v1='The v1 status bar content (On air, displays, queue count) is kept as the right zone.',
  accept='LIVE zone shows the same item as the Live box in 100 % of samples; at 1040 px the dock does not wrap; contrast audit clean in all themes.'),
 dict(id='P-06', title='A Run view for services: queue and live first, finding tucked away', effort='L', risk='med', impact='high',
  one='When the screens are on and the queue has items, offer a layout that puts the queue, the live and preview boxes and Next/Back at the centre; finding things opens as a slide-over.',
  problem='During a service the volunteer mostly steps through a prepared queue, but the layout is the preparation layout: browse columns and a reading pane take two thirds of the window while the queue (the thing in use) has a third, and the Preview/Live pair is at the bottom right at 100 px wide. At 1040×640 the work area is 501 px; at 150 % it is smaller still. The Take/Next/Back buttons are the most important controls and are 36 px high.',
  change='A "Run" toggle (also automatic when the projection opens, with a one-line "Back to Prepare") that shows: left, the queue as large rows (current and next highlighted); right, big Preview and Live (about 360 px wide) with Show next, Back, Next, Hide screen as large targets; ⌘K / "Find" opens Sermons, Bible, Songs, Media as a slide-over for a last-minute change. Prepare view stays exactly as today.',
  benefit='A volunteer at 9:55 sees only what a service needs; the critical buttons become large; a last-minute change is still two keystrokes (⌘K then the verse).',
  files='App.tsx layout, new RunView component reusing QueuePanel rows, PreviewLivePair, DrillShell slide-over; CommandPalette launch.',
  migration='A setting "Switch to Run view when the screens open" (default on for new profiles, off for existing).',
  v1='Prepare = today; nothing is removed.',
  accept='In Run view at 1040×640 the queue shows ≥ 7 rows, Show next ≥ 44 px high; ⌘K → verse → Show works without leaving Run view; undo and Esc rules unchanged.'),
 dict(id='P-07', title='One primary button in the live box (Show next), steps become small arrows', effort='M', risk='med', impact='high',
  one='"Take next" and "Next ›" are two big purple buttons that do different things. Keep one primary: Show next.',
  problem='The live box has two same-weight purple buttons: Take next (send the previewed item live) and Next › (step the queue forward) plus Back ‹ and Clear. In the manual they are explained at length. Under stress the likelihood of pressing the wrong one is real: Next moves on without the volunteer noticing what is previewed.',
  change='Show next ▸ is the only large primary (Space, as today). Back/Next become compact arrows beside the title of the Preview box ("‹ 3 of 12 ›"). Clear and Hide screen sit on the Live box. Colour: plum = action, red = live only.',
  benefit='One obvious action; accidental step-forward is less likely; the live box is shorter (about 40 px).',
  files='components/PreviewLivePair, QueuePanel footer buttons, webRemote.ts (phone mirrors it), tests for keyboard mapping.',
  migration='Keyboard stays: → / Space next, ← back. Phone: Prev/Next stay big (a phone has no keyboard).',
  v1='Space/arrow behaviour is identical.', accept='The same keystrokes produce the same results as today (existing tests moved); a new test pins the single primary.'),
 dict(id='P-08', title='Rows: one click selects, one key shows; actions appear on hover or focus', effort='M', risk='med', impact='med',
  one='Every Bible verse and sermon paragraph carries "+ Queue" and "Project" buttons and also says "Tap a verse to put it on screen". Choose one gesture.',
  problem='Each row has three ways to send it (click the row, Project, Enter) and a fourth to queue (+ Queue, Q). The result: a dense column of repeated buttons (24 verse rows × 2 buttons), large body text that shows only two verses at 1366×768, and uncertainty about whether a click shows or selects.',
  change='Click selects (and previews); Enter or double-click shows; hover/focus reveals two small buttons (Queue, Show) so the row reads as text. Same pattern for Bible, Sermons, Songs and Media. The hint line says it once.',
  benefit='Cleaner reading surface; the same gesture everywhere; fewer accidental sends (the single click no longer puts text live).',
  files='BiblePanel, SermonFollowView, SongsPanel, MediaPanel row components; ContextMenu entries unchanged.',
  migration='A one-time hint on first use. Setting "Click shows immediately" for people who prefer v1 behaviour.',
  v1='Right-click menus and keyboard are unchanged.', accept='Click never changes what is live unless the setting is on (CLAUDE.md rule); keyboard Enter shows; every row still reachable by Tab.'),
 dict(id='P-09', title='Bigger targets where it matters (Fitts) and a minimum size everywhere', effort='S', risk='low', impact='med',
  one='The measured controls under 24 px (Help, Shortcuts, subtabs, "Add pictures", filters) become at least 32 px; Show, Hide screen, Play and Panic at least 40 px.',
  problem='A DOM probe at 1366×768 found, per section, 10–15 visible controls under 24 px high and 19–28 under 32 px (of 32–46 visible): btn-sm, subtabs, Help, filters. Open/Close projection and Hide screen, the controls that matter most under pressure, are only 28 px high. The phone remote already meets 44 px.',
  change='A target-size token (min 32 desktop, 40 for live-critical, 44 on touch) applied to btn-sm, subtabs and links; Show, Hide screen, Play get the larger tier. No visual redesign; padding only.',
  benefit='Fewer mis-clicks on a trackpad in a dark booth; easier on touch laptops.',
  files='App.css (.btn-sm, .panel-subtab, .btn-quiet), component CSS; one new test that scans the CSS for heights under the minimum.',
  migration='None.', v1='Same look, slightly roomier.', accept='A DOM probe finds no interactive control under 32 px except text links inside paragraphs; live-critical ≥ 40 px.'),
 dict(id='P-10', title='Skip links, landmarks and a content-first tab order', effort='S', risk='low', impact='med',
  one='Reaching the first control of a section takes 26 Tab presses; there is no skip link and no heading level 1.',
  problem='Keyboard-only walkthrough: Tab starts in the header (13 stops) and the rail (8 stops) and the section tabs (5) before the content. There is no "skip to content", no h1, the queue pane is not a landmark, and Tab does not reach the queue pane from the content without crossing everything again.',
  change='Skip links ("Skip to content", "Skip to the queue", "Skip to the live controls") visible on focus; one h1 per section; the queue pane as a complementary landmark; F6 cycles the main regions (header, rail, content, queue, dock).',
  benefit='Keyboard operators and screen-reader users reach their target in 1–2 keystrokes; the same F6 helps sighted keyboard users.',
  files='App.tsx (skip links, landmarks, F6), a11y test additions.', migration='None.', v1='Nothing changes for mouse users.',
  accept='Tab from page start reaches "Skip to content" first; F6 cycles regions; axe landmark and heading checks pass.'),
 dict(id='P-11', title='Appearance and interface size in one place', effort='S', risk='low', impact='low',
  one='Theme and high contrast are header buttons, the interface size is only in the command palette, and language/fonts are elsewhere. Put them in the ⚙ menu (P-01).',
  problem='The interface size (100–175 %) is the one setting that decides whether the app is usable on a small or very large screen and it is found only through the palette ("Interface size…"). Theme and contrast are two separate icon buttons whose icons are not self-explanatory (a sun and a half-filled circle).',
  change='⚙ Appearance: Theme (Dark / Light), Contrast (Normal / High), Interface size (Auto / 100 / 125 / 150 / 175 %) with a live preview line. The two icon buttons leave the header.',
  benefit='Discoverable; one decision at a time.', files='SettingsMenu (new), uiScale.ts, useTheme.ts.', migration='Existing choices persist (same storage keys).',
  v1='The sun and contrast icons remain in the menu next to the words.', accept='All three settings reachable by keyboard; persisted; reduced-motion respected.'),
 dict(id='P-12', title='First run: a short "Set up Sunday" checklist and quick-start templates', effort='M', risk='low', impact='med',
  one='A new profile opens straight into an empty Sermons search; nothing tells a first-time volunteer what to do first.',
  problem='On a fresh profile the app shows "Type a word or phrase above to search sermon quotes" and an empty queue. There is no first-run guidance beyond Help. The volunteer who has used the app twice has no path from "open" to "ready".',
  change='An empty-queue card with a four-step checklist (Choose screens → Open projection test pattern → Add tonight\'s items → Check "Is tonight ready?") and three templates (Sunday morning: song, scripture, sermon, song; Midweek; Funeral). Each step opens the real control; the card disappears once the queue has items and can be re-opened from Help.',
  benefit='The first service is guided; fewer questions to the owner; templates save ~10 clicks per week.',
  files='QueuePanel empty state, Preflight, a templates module (data only), Help.', migration='New profiles only; existing profiles see it once, dismissible.',
  v1='None removed.', accept='Fresh profile shows the checklist; each step performs the real action; dismissal persists.'),
 dict(id='P-13', title='Phone remote: Media and Tape tabs, a clear blank state, and bigger Blank', effort='S', risk='low', impact='med',
  one='The remote has Queue, Sermons, Bible, Songs but no Media or Tape tab; when the screen is hidden the only sign is the colour of the Blank button.',
  problem='The remote\'s bottom navigation (phone) and side rail (tablet) list Queue, Sermons, Bible and Songs (Media and Tape have no tab of their own); the Blank button is amber in both states (blanked or not); there is no "Hidden" banner. The tape card appears only when a tape is loaded.',
  change='Add Media (pictures and the Send-to-screen shortcut) and Tape tabs (the tape card plus the follow list); a full-width "SCREEN HIDDEN — Show" banner when blanked; Blank grows to 56 px.',
  benefit='The person holding the phone can do everything a walking operator needs; state is obvious without reading colours.',
  files='src/main/webRemote.ts (the remote\'s HTML/CSS/JS), tests in webRemote tests, Chromium and WebKit remote scripts.', migration='None; the remote auto-updates with the app.',
  v1='The v1 remote tabs and layout are unchanged.', accept='Remote regression (Chromium and WebKit) passes at 360×640, 390×844 and tablet; banner shown in the blanked state.'),
]
ORDER = ['P-02','P-03','P-09','P-10','P-04','P-01','P-11','P-05','P-07','P-13','P-08','P-12','P-06']
